#include <queue>
#include <vector>
#include <list>

int main() {
    std::list<double> source = {3.1, 1.9, 4.5};

    // Initializing a priority_queue<int> from a range of doubles.
    // Doubles are converted to ints (3, 1, 4).
    std::priority_queue<int> pq_int(
        source.begin(), 
        source.end()
    );

    // Top element is max (4)
    if (!pq_int.empty()) {
        // Output: 4
        std::cout << "Top element (converted): " << pq_int.top() << "\n";
    }
}
